#include &lt;hip/hip_runtime.h&gt;

__constant__ float INV_SQRT_2 = 0.70710678118654752440f;

__global__ void fused_linear_gelu_kernel(const float* __restrict__ x, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ out, int B, int K, int N) {
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx &gt;= B * N) {
        return;
    }
    int b = idx / N;
    int j = idx % N;
    float acc = bias[j];
    for (int k = 0; k &lt; K; ++k) {
        acc += x[b * K + k] * weight[j * K + k];
    }
    float arg = acc * INV_SQRT_2;
    out[idx] = 0.5f * acc * (1.0f + erf(arg));
}

torch::Tensor fused_linear_gelu_hip(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    int64_t B = x.size(0);
    int64_t K = x.size(1);
    int64_t N = weight.size(0);
    auto out = torch::empty({B, N}, x.options());
    dim3 block_size(256);
    dim3 num_blocks((B * N + block_size.x - 1) / block_size.x);
    hipLaunchKernelGBL(
        fused_linear_gelu_kernel,
        num_blocks,
        block_size,
        0,
        0,
        x.data_ptr&lt;float&gt;(), 
        weight.data_ptr&lt;float&gt;(),
        bias.data_ptr&lt;float&gt;(), 
        out.data_ptr&lt;float&gt;(),
        B, K, N
    );
    return out;
}
"""

